#### Example 1: React Component Contract Test

_[To be completed]_

```typescript
// Contract test for extension component props
import { render, screen } from '@testing-library/react';
import { ClaimsValidator } from '@gainwell/texas-claims-extension';

describe('ClaimsValidator Contract', () => {
  it('accepts required props', () => {
    const props = {
      claimId: 'CLM-12345',
      tenantId: 'texas',
      context: { userId: 'user-1' }
    };

    render(<ClaimsValidator {...props} />);
    expect(screen.getByTestId('claims-validator')).toBeInTheDocument();
  });

  it('calls onValidationComplete callback', async () => {
    const onValidationComplete = jest.fn();
    const props = {
      claimId: 'CLM-12345',
      tenantId: 'texas',
      onValidationComplete
    };

    render(<ClaimsValidator {...props} />);
    // Trigger validation
    await waitFor(() => {
      expect(onValidationComplete).toHaveBeenCalledWith(
        expect.objectContaining({ isValid: expect.any(Boolean) })
      );
    });
  });
});
```

