#### Example 2: Module Federation Integration Test

_[To be completed]_

```typescript
// Integration test for Module Federation loading
import { test, expect } from '@playwright/test';

test('loads Texas claims extension dynamically', async ({ page }) => {
  await page.goto('http://localhost:3000/claims/detail/CLM-12345');

  // Wait for extension to load
  await page.waitForSelector('[data-extension="texas-claims-validator"]');

  // Verify extension rendered
  const extension = await page.locator('[data-extension="texas-claims-validator"]');
  await expect(extension).toBeVisible();

  // Verify extension functionality
  await extension.locator('button[type="submit"]').click();
  await expect(page.locator('.validation-result')).toBeVisible();
});
```

