#### Example 4: Accessibility Compliance Test

_[To be completed]_

```typescript
// Accessibility test for extension component
import { render } from '@testing-library/react';
import { axe, toHaveNoViolations } from 'jest-axe';

expect.extend(toHaveNoViolations);

test('extension has no accessibility violations', async () => {
  const { container } = render(
    <ClaimsValidator
      claimId="CLM-12345"
      tenantId="texas"
    />
  );

  const results = await axe(container);
  expect(results).toHaveNoViolations();
});
```
